CREATE TABLE IF NOT EXISTS schema_migrations(version INT PRIMARY KEY, applied_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6));
CREATE TABLE IF NOT EXISTS users(id VARCHAR(32) PRIMARY KEY,email VARCHAR(254) NOT NULL UNIQUE,nickname VARCHAR(40) NOT NULL,bio VARCHAR(300) NOT NULL DEFAULT '',avatar_id VARCHAR(32) NULL,password_hash VARBINARY(255) NOT NULL,created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6));
CREATE TABLE IF NOT EXISTS email_codes(email VARCHAR(254) PRIMARY KEY,code_hash CHAR(64) NOT NULL,expires_at DATETIME(6) NOT NULL,attempts INT NOT NULL DEFAULT 0,sent_at DATETIME(6) NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash CHAR(64) PRIMARY KEY,user_id VARCHAR(32) NOT NULL,expires_at DATETIME(6) NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS media(id VARCHAR(32) PRIMARY KEY,user_id VARCHAR(32) NOT NULL,mime VARCHAR(40) NOT NULL,body MEDIUMBLOB NOT NULL,created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS posts(id VARCHAR(32) PRIMARY KEY,author_id VARCHAR(32) NOT NULL,type VARCHAR(20) NOT NULL,published_revision_id VARCHAR(32) NULL,draft_revision_id VARCHAR(32) NULL,status VARCHAR(20) NOT NULL DEFAULT 'draft',created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6),published_at DATETIME(6) NULL,FOREIGN KEY(author_id) REFERENCES users(id),INDEX(status,published_at,id));
CREATE TABLE IF NOT EXISTS revisions(id VARCHAR(32) PRIMARY KEY,post_id VARCHAR(32) NOT NULL,title VARCHAR(120) NOT NULL,body TEXT NOT NULL,category VARCHAR(40) NOT NULL,media_ids JSON NOT NULL,opportunity JSON NULL,state VARCHAR(20) NOT NULL DEFAULT 'draft',reason VARCHAR(500) NOT NULL DEFAULT '',created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(post_id) REFERENCES posts(id));
CREATE TABLE IF NOT EXISTS comments(id VARCHAR(32) PRIMARY KEY,post_id VARCHAR(32) NOT NULL,author_id VARCHAR(32) NOT NULL,body VARCHAR(2000) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(post_id) REFERENCES posts(id),FOREIGN KEY(author_id) REFERENCES users(id),INDEX(post_id,status,created_at));
CREATE TABLE IF NOT EXISTS review_tasks(id VARCHAR(32) PRIMARY KEY,kind VARCHAR(20) NOT NULL,target_id VARCHAR(32) NOT NULL UNIQUE,author_id VARCHAR(32) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',decision VARCHAR(20) NULL,reason VARCHAR(500) NOT NULL DEFAULT '',reviewer VARCHAR(254) NULL,created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6),decided_at DATETIME(6) NULL,INDEX(status,created_at));
CREATE TABLE IF NOT EXISTS follows(follower_id VARCHAR(32) NOT NULL,followee_id VARCHAR(32) NOT NULL,created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(follower_id,followee_id),FOREIGN KEY(follower_id) REFERENCES users(id),FOREIGN KEY(followee_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS reactions(user_id VARCHAR(32) NOT NULL,post_id VARCHAR(32) NOT NULL,kind VARCHAR(12) NOT NULL,created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(user_id,post_id,kind),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(post_id) REFERENCES posts(id));
CREATE TABLE IF NOT EXISTS reports(id VARCHAR(32) PRIMARY KEY,user_id VARCHAR(32) NOT NULL,post_id VARCHAR(32) NOT NULL,reason VARCHAR(500) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',result VARCHAR(500) NOT NULL DEFAULT '',created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(post_id) REFERENCES posts(id));
CREATE TABLE IF NOT EXISTS appeals(id VARCHAR(32) PRIMARY KEY,user_id VARCHAR(32) NOT NULL,task_id VARCHAR(32) NOT NULL,reason VARCHAR(1000) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6),UNIQUE(user_id,task_id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(task_id) REFERENCES review_tasks(id));
CREATE TABLE IF NOT EXISTS outbox(id VARCHAR(32) PRIMARY KEY,kind VARCHAR(40) NOT NULL,aggregate_id VARCHAR(32) NOT NULL,payload JSON NOT NULL,created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6),processed_at DATETIME(6) NULL,INDEX(processed_at,created_at));
CREATE TABLE IF NOT EXISTS feed_items(user_id VARCHAR(32) NOT NULL,post_id VARCHAR(32) NOT NULL,published_at DATETIME(6) NOT NULL,PRIMARY KEY(user_id,post_id),INDEX(user_id,published_at,post_id));
CREATE TABLE IF NOT EXISTS notifications(id VARCHAR(32) PRIMARY KEY,user_id VARCHAR(32) NOT NULL,event_id VARCHAR(32) NOT NULL,message VARCHAR(500) NOT NULL,post_id VARCHAR(32) NULL,read_at DATETIME(6) NULL,created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6),UNIQUE(user_id,event_id));
CREATE TABLE IF NOT EXISTS audit_log(id VARCHAR(32) PRIMARY KEY,actor VARCHAR(254) NOT NULL,action VARCHAR(40) NOT NULL,target_id VARCHAR(32) NOT NULL,reason VARCHAR(1000) NOT NULL,created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6));
CREATE TABLE IF NOT EXISTS idempotency(user_id VARCHAR(32) NOT NULL,request_key VARCHAR(80) NOT NULL,operation VARCHAR(40) NOT NULL,body_hash CHAR(64) NOT NULL,resource_id VARCHAR(32) NOT NULL,created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(user_id,request_key,operation));
INSERT IGNORE INTO schema_migrations(version) VALUES(1);
